CommonData.BannerCustomCSS:
/* Style adjustments for the container */
#onetrust-consent-sdk #onetrust-banner-sdk {
    background-color: var(--system-bg-elevation-layer-1, #FFFFFF ) !important;
    border-radius: var(--radius-lg, 16px) !important;
		font-family: Inter !important;
}

#onetrust-consent-sdk #onetrust-banner-sdk *:focus,
#onetrust-consent-sdk #onetrust-banner-sdk:focus {
    outline: none;
    box-shadow: inset 0 0 0 1px var(--system-bg-data-blue-primary, #0071d8), 0 0 0 2px var(--system-bg-data-blue-secondary, #ccdff6) !important;
}

#onetrust-banner-sdk.ot-wo-title #onetrust-group-container {
    margin-top: 0px;
}

#onetrust-banner-sdk #onetrust-policy-text {
    padding-bottom: 16px !important;
}

/* Policy text */
#onetrust-policy-text,
#onetrust-policy-text a {
    font-size: 14px !important;
    font-weight: 400 !important;
    line-height: 1.42857 !important;
    color: var(--system-text-on-elevation-primary, #2B343A) !important;
}

#onetrust-policy-text a {
    color: var(--system-text-on-elevation-link, #E10103) !important;
}

/* Style adjustments for all relevant buttons */
#onetrust-accept-btn-handler,
#onetrust-pc-btn-handler,
#onetrust-reject-all-handler,
#ot-sdk-btn { 
    min-width: 170px !important;
    border-radius: var(--radius-full, 1000px) !important;
    box-shadow: none !important;
    border: none !important;
    font-size: 16px !important;
    font-weight: 600 !important;
    line-height: 1.25 !important;
}

/* Specific styles for buttons */
#onetrust-accept-btn-handler { 
    background-color: var(--component-button-primary-bg, #E10103) !important;
    color: var(--component-button-primary-text, #FFFFFF) !important;
}

#onetrust-reject-all-handler { 
    background-color: var(--component-button-secondary-bg, rgba(97,114,126,0.16)) !important;
    color: var(--component-button-secondary-text, #2B343A) !important;
}
#onetrust-pc-btn-handler { 
    background-color: transparent !important;
    color: var(--component-button-text-primary-default, #E10103);
}

/* Media query adjustments */
@media (max-width: 768px) {
    #onetrust-banner-sdk #onetrust-button-group-parent:not(.has-reject-all-button) #onetrust-accept-btn-container #onetrust-accept-btn-handler,
    #onetrust-banner-sdk #onetrust-button-group-parent:not(.has-reject-all-button) #onetrust-reject-all-btn-container #onetrust-reject-all-handler,
    #onetrust-banner-sdk #onetrust-button-group-parent:not(.has-reject-all-button) #onetrust-accept-btn-container #ot-sdk-btn { 
        width: 100% !important;
    }
}

@media (max-width: 425px) {
    #onetrust-banner-sdk #onetrust-button-group-parent:not(.has-reject-all-button) #onetrust-accept-btn-container #onetrust-accept-btn-handler,
    #onetrust-banner-sdk #onetrust-button-group-parent:not(.has-reject-all-button) #onetrust-reject-all-btn-container #onetrust-reject-all-handler,
    #onetrust-banner-sdk #onetrust-button-group-parent:not(.has-reject-all-button) #onetrust-accept-btn-container #ot-sdk-btn { 
        width: 100% !important;
    }
}

/* Style adjustments for the settings banner */
#onetrust-pc-sdk {
    background-color: var(--system-bg-elevation-layer-1, #FFFFFF) !important;
    font-family: Inter !important;
}

#onetrust-pc-sdk .ot-pc-header {
    border-bottom: 1px solid var(--system-border-on-elevation-tertiary, #e9ebed) !important;
}

#onetrust-pc-sdk button {
    font-size: 16px !important;
    font-weight: 600 !important;
    line-height: 1.25 !important;
    border-radius: var(--radius-full, 1000px) !important;
    border: none !important;
}

#onetrust-pc-sdk #accept-recommended-btn-handle {
    width: 100% !important;
    max-width: 100% !important;
    background: var(--system-bg-elevation-brand, #fef0f1) !important;
    color: var(--system-text-on-elevation-link, #e10103) !important;
}

#onetrust-pc-sdk .ot-pc-refuse-all-handler {
    background: var(--component-button-secondary-bg, rgba(97, 114, 126, 0.16)) !important;
    color: var(--system-text-on-elevation-link, #e10103) !important;
}

#onetrust-pc-sdk .save-preference-btn-handler {
    background: var(--component-button-primary-bg, #e10103) !important;
    color: var(--component-button-primary-text, #FFFFFF) !important;
}

#onetrust-pc-sdk .ot-pc-title,
#onetrust-pc-sdk #ot-pc-desc,
#onetrust-pc-sdk .ot-category-title,
#onetrust-pc-sdk .ot-cat-header {
    color: var(--system-text-on-elevation-primary, #2b343a) !important;
}

#onetrust-pc-sdk .ot-pc-title {
    font-size: 18px !important;
    font-weight: 700 !important;
    line-height: 1.33333 !important;
}

#onetrust-pc-sdk #ot-pc-desc {
    font-size: 14px !important;
    font-weight: 400 !important;
    line-height: 1.42857 !important;
}

#onetrust-pc-sdk .privacy-notice-link {
    color: var(--system-text-on-elevation-link, #e10103) !important;
    font-size: 14px !important;
    font-weight: 600 !important;
    line-height: 1.28571 !important;
}

#onetrust-pc-sdk .ot-category-title {
    font-size: 18px !important;
    font-weight: 700 !important;
    line-height: 1.33333 !important;
}

#onetrust-pc-sdk .ot-cat-header {
    font-size: 14px !important;
    font-weight: 600 !important;
    line-height: 1.28571 !important;
}

#onetrust-pc-sdk .ot-always-active {
    color: var(--system-text-on-elevation-link, #e10103) !important;
    font-size: 14px !important;
    font-weight: 600 !important;
    line-height: 1.28571 !important;
}

#onetrust-pc-sdk .ot-always-active svg path.ot-arw {
    fill: var(--system-graphics-on-elevation-secondary, #3c4851) !important;
}

#onetrust-pc-sdk .ot-accordion-layout {
    border-color: var(--system-border-on-elevation-secondary, #cad0d4) !important;
}

#onetrust-pc-sdk .ot-accordion-layout:first-child   {
    border-top-left-radius: var(--radius-md, 10px) !important;
    border-top-right-radius: var(--radius-md, 10px) !important;

}
#onetrust-pc-sdk .ot-accordion-layout:last-child   {
    border-bottom-left-radius: var(--radius-md, 10px) !important;
    border-bottom-right-radius: var(--radius-md, 10px) !important;
}

#onetrust-pc-sdk .ot-switch-nob {
    background-color: var(--system-bg-elevation-layer-2, #f2f4f5) !important;
    border-color: var(--system-border-on-elevation-tertiary, #e9ebed) !important;
}

#onetrust-pc-sdk .ot-switch-nob:before {
    background-color: var(--system-bg-neutral, #0071d8) !important;
}

#onetrust-pc-sdk .ot-acc-grpcntr.ot-acc-txt {
    background-color: var(--system-bg-elevation-layer-1, #FFFFFF) !important;
}

#onetrust-pc-sdk .ot-acc-grpcntr.ot-acc-txt {
    color: var(--system-text-on-elevation-primary, #2b343a) !important;
}

#onetrust-pc-sdk .ot-link-btn.category-host-list-handler {
    color: var(--system-text-on-elevation-link, #e10103) !important;
}

#onetrust-consent-sdk #onetrust-policy-title {
    color: var(--system-text-on-elevation-primary, #2B343A) !important;
}

#onetrust-banner-sdk div {
		font-family: Inter, sans-serif !important;
}

